const {
  Document, Packer, Paragraph, TextRun, HeadingLevel,
  AlignmentType, BorderStyle, ShadingType
} = require('docx');
const fs = require('fs');

function heading1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    children: [new TextRun({ text, font: "Arial", size: 32, bold: true, color: "C9727A" })],
    spacing: { before: 360, after: 160 }
  });
}

function heading2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    children: [new TextRun({ text, font: "Arial", size: 26, bold: true, color: "333333" })],
    spacing: { before: 300, after: 120 }
  });
}

function label(text) {
  return new Paragraph({
    children: [new TextRun({ text: text.toUpperCase(), font: "Arial", size: 18, bold: true, color: "999999", characterSpacing: 40 })],
    spacing: { before: 240, after: 60 }
  });
}

function body(text) {
  const lines = text.split('\n');
  return lines.map((line, i) =>
    new Paragraph({
      children: [new TextRun({ text: line, font: "Arial", size: 22, color: "333333" })],
      spacing: { before: i === 0 ? 0 : 40, after: 40 },
      indent: { left: 360 }
    })
  );
}

function divider() {
  return new Paragraph({
    border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: "EEEEEE", space: 1 } },
    spacing: { before: 200, after: 200 }
  });
}

function spacer() {
  return new Paragraph({ children: [new TextRun("")], spacing: { before: 80, after: 80 } });
}

const children = [
  // Title block
  new Paragraph({
    children: [new TextRun({ text: "Medspa Outreach Copy", font: "Arial", size: 48, bold: true, color: "1A1A1A" })],
    spacing: { before: 0, after: 80 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "DM Templates + Group Post Templates", font: "Arial", size: 22, color: "888888" })],
    spacing: { before: 0, after: 40 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "The Luxora Collective  |  Prepared for Aanchal", font: "Arial", size: 20, color: "AAAAAA" })],
    spacing: { before: 0, after: 80 }
  }),
  new Paragraph({
    border: { bottom: { style: BorderStyle.SINGLE, size: 8, color: "C9727A", space: 1 } },
    spacing: { before: 0, after: 400 }
  }),

  // SECTION 1: Cold DMs
  heading1("Cold DM Templates"),
  new Paragraph({
    children: [new TextRun({ text: "Send these as direct messages to medspa owners on Facebook or Instagram. Swap in their name and replace [link] with your landing page URL.", font: "Arial", size: 20, color: "666666" })],
    spacing: { before: 0, after: 200 }
  }),

  label("DM Option 1 — Curiosity Hook"),
  ...body("Hey [Name]! Quick question for you...\n\nWhen it's slow at your medspa, what does your team actually do?\n\nI put together a free resource called \"What do winning teams do when it's slow?\" — 101 strategies to turn downtime into profit. It's literally ready to print and post in your break room.\n\nIf you want it, I'll send you the link. No strings attached."),
  spacer(),

  divider(),

  label("DM Option 2 — Empathy-Led"),
  ...body("Hey [Name]! I've been thinking about medspa owners lately...\n\nSlow days are honestly one of the most stressful parts of running a practice. Your team is standing around, revenue stalls, and it feels like nothing's working.\n\nSo I put together something free for you: 101 ways to turn downtime into actual profit. It's called \"What do winning teams do when it's slow?\" and it's formatted to print and hang in your break room.\n\nWant me to drop the link?"),
  spacer(),

  divider(),

  label("DM Option 3 — Short and Snappy"),
  ...body("Hi [Name]! I made something you might love...\n\nIt's a free guide: 101 ways your team can turn a slow day into profit. Ready to print and post in your break room.\n\nIt's called \"What do winning teams do when it's slow?\" and it's totally free.\n\nWant the link?"),
  spacer(),

  divider(),

  label("DM Option 4 — After a Like or Follow"),
  ...body("Hey [Name]! Thanks for following along.\n\nI wanted to share something with you since you're in the medspa world...\n\nI have a free resource called \"What do winning teams do when it's slow?\" It's 101 strategies to get profit between appointments, formatted to print and post in your break room.\n\nA lot of owners have found it super helpful for slow seasons. Want me to send it over?"),
  spacer(),

  // SECTION 2: Follow-Up Sequence
  new Paragraph({ children: [new TextRun("")], pageBreakBefore: true }),
  heading1("Follow-Up DM Sequence"),
  new Paragraph({
    children: [new TextRun({ text: "Use this sequence after a prospect says yes to receiving the free guide. Message 1 goes out immediately. The rest follow every few days if there is no reply.", font: "Arial", size: 20, color: "666666" })],
    spacing: { before: 0, after: 200 }
  }),

  label("Message 1 — Send Immediately When They Say Yes"),
  ...body("Yes!! So glad you wanted this. Here's your link:\n\n[insert link]\n\nIt's 101 strategies your team can use on slow days to create profit instead of just passing time. Print it, post it in your break room, and let it do the work for you.\n\nOne thing I'd love to know: what's the biggest challenge your practice is dealing with right now when it comes to revenue? Slow days? Retaining clients? Getting people to book more than once?\n\nI ask because I work with medspa owners on exactly this stuff and I'd love to point you in the right direction."),
  spacer(),

  divider(),

  label("Message 2 — Send 1-2 Days Later (If No Reply)"),
  ...body("Hey [Name]! Just checking in to make sure the link worked for you.\n\nDid you get a chance to look through it? I'd love to know which strategies jumped out at you first.\n\nSome of my clients' favorites are around reactivating lapsed clients and building simple packages their front desk can offer during checkout. Total game changers for filling a slow week."),
  spacer(),

  divider(),

  label("Message 3 — Send 3-4 Days Later (If Still No Reply)"),
  ...body("Hey [Name]! No pressure at all, just wanted to share something quick.\n\nI work with medspa owners through a program called the 90-Day Growth Engine. It's basically a done-with-you system to turn one-time clients into lifetime clients, build a membership, and create consistent revenue, without burning yourself out.\n\nIf that sounds like something you'd want to hear more about, I'd love to do a quick 20-minute call just to learn about your practice and see if it could be a fit.\n\nNo pitch, just a real conversation. Want to grab a time?"),
  spacer(),

  divider(),

  label("Message 4 — Send 5-7 Days Later (Last Touch)"),
  ...body("Hey [Name]! Last thing from me, I promise.\n\nI just wanted to leave the door open. If you ever find yourself thinking \"I need more consistent revenue\" or \"I feel like my clients aren't coming back the way they should,\" that's exactly what I help with.\n\nYou can always reach back out here or book a call when the timing feels right: [calendar link]\n\nEither way, I hope the guide is helpful. Rooting for your practice!"),
  spacer(),

  // SECTION 3: Group Posts
  new Paragraph({ children: [new TextRun("")], pageBreakBefore: true }),
  heading1("Facebook Group Post Templates"),
  new Paragraph({
    children: [new TextRun({ text: "Drop these in medspa owner Facebook groups. Value-first, no hard pitch. Replace [link] with your landing page URL.", font: "Arial", size: 20, color: "666666" })],
    spacing: { before: 0, after: 200 }
  }),

  label("Group Post Option 1 — Question Starter"),
  ...body("Honest question for medspa owners: what does your team do on slow days?\n\nBecause there's a BIG difference between a team that kills time and a team that kills it.\n\nI put together a free guide, \"What do winning teams do when it's slow?\" — 101 strategies to turn downtime into profit. Print it out and post it in your break room so your staff always knows what to do when it's quiet.\n\nGet it free here: [link]\n\nWould love to know what's currently working for you all during your slow seasons. Drop it in the comments!"),
  spacer(),

  divider(),

  label("Group Post Option 2 — Teaching Post with CTA"),
  ...body("The most profitable medspas I've worked with have one thing in common...\n\nThey don't wait for business to come to them during a slow day. Their teams know exactly what to do to create revenue, build loyalty, and fill the schedule.\n\nIt's not magic. It's a system.\n\nI put together 101 ways to turn a slow day into a profit day and made it free: \"What do winning teams do when it's slow?\"\n\nIt's formatted to print and post right in your break room so your team always has a game plan.\n\nGrab it here: [link]"),
  spacer(),

  divider(),

  label("Group Post Option 3 — Relatable + Resource"),
  ...body("Raise your hand if slow days at your medspa feel like wasted money.\n\nSame. And the worst part? It doesn't have to be that way.\n\nI created a totally free guide called \"What do winning teams do when it's slow?\" because I kept seeing medspa owners and their staff not knowing what to do when the schedule opened up.\n\n101 strategies. Print-and-post format. Free.\n\nGrab it here: [link]\n\nTag a medspa owner who needs this!"),
  spacer(),

  divider(),

  label("Group Post Option 4 — Short Punchy Drop"),
  ...body("Free for medspa owners:\n\n\"What do winning teams do when it's slow?\" — 101 strategies to turn downtime into profit.\n\nFormatted to print and post in your break room. No fluff, no upsell. Just 101 things your team can actually DO to generate revenue between appointments.\n\nGet it here: [link]\n\nSave this post and share it with another owner who could use it!"),
  spacer(),

  // Footer
  new Paragraph({
    border: { top: { style: BorderStyle.SINGLE, size: 4, color: "EEEEEE", space: 1 } },
    spacing: { before: 400, after: 100 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "The Luxora Collective  |  theluxoracollective.co  |  Bethany Anne", font: "Arial", size: 18, color: "AAAAAA" })],
    alignment: AlignmentType.CENTER,
    spacing: { before: 0, after: 0 }
  }),
];

const doc = new Document({
  styles: {
    default: { document: { run: { font: "Arial", size: 22 } } }
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 }
      }
    },
    children
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync('/home/claude/medspa_outreach.docx', buffer);
  console.log('Done!');
});

