const {
  Document, Packer, Paragraph, TextRun, HeadingLevel,
  AlignmentType, BorderStyle, ShadingType, WidthType,
  Table, TableRow, TableCell, VerticalAlign, LevelFormat
} = require('docx');
const fs = require('fs');

const pink = "C9727A";
const dark = "1A1A1A";
const mid = "444444";
const muted = "777777";
const light = "F7F3F3";
const border = { style: BorderStyle.SINGLE, size: 4, color: "EEEEEE" };
const borders = { top: border, bottom: border, left: border, right: border };

function h1(text) {
  return new Paragraph({
    children: [new TextRun({ text, font: "Arial", size: 30, bold: true, color: pink })],
    spacing: { before: 320, after: 120 }
  });
}

function h2(text) {
  return new Paragraph({
    children: [new TextRun({ text, font: "Arial", size: 24, bold: true, color: dark })],
    spacing: { before: 240, after: 80 }
  });
}

function bodyText(text, color = mid) {
  return new Paragraph({
    children: [new TextRun({ text, font: "Arial", size: 20, color })],
    spacing: { before: 40, after: 60 },
    indent: { left: 0 }
  });
}

function tip(emoji, text) {
  return new Paragraph({
    children: [
      new TextRun({ text: emoji + "  ", font: "Arial", size: 20 }),
      new TextRun({ text, font: "Arial", size: 20, color: mid })
    ],
    spacing: { before: 60, after: 60 },
    indent: { left: 360 }
  });
}

function warningBox(text) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [
      new TableRow({
        children: [
          new TableCell({
            borders,
            width: { size: 9360, type: WidthType.DXA },
            shading: { fill: "FFF3F3", type: ShadingType.CLEAR },
            margins: { top: 120, bottom: 120, left: 180, right: 180 },
            children: [
              new Paragraph({
                children: [
                  new TextRun({ text: "⚠  IMPORTANT: ", font: "Arial", size: 20, bold: true, color: "B94A4A" }),
                  new TextRun({ text, font: "Arial", size: 20, color: "B94A4A" })
                ],
                spacing: { before: 0, after: 0 }
              })
            ]
          })
        ]
      })
    ]
  });
}

function noteBox(text) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [
      new TableRow({
        children: [
          new TableCell({
            borders,
            width: { size: 9360, type: WidthType.DXA },
            shading: { fill: "FDF0F1", type: ShadingType.CLEAR },
            margins: { top: 120, bottom: 120, left: 180, right: 180 },
            children: [
              new Paragraph({
                children: [
                  new TextRun({ text: "💡  TIP: ", font: "Arial", size: 20, bold: true, color: pink }),
